	private static Exists nestedDomainNotExists(int domain, int keyColumn, int valueColumn,
			boolean nonReusableFilter) {
		java.util.ArrayList<Node> pipeline = new java.util.ArrayList<>();
		pipeline.add(new EnumerateDomain(domain, keyColumn, false, null, false));
		pipeline.add(new Probe(domain, Operand.col(keyColumn), valueColumn));
		pipeline.add(new FilterCompareId(false, Operand.col(valueColumn), Operand.col(BRANCH)));
		if (nonReusableFilter) {
			pipeline.add(new FilterValue(0, new Operand[] { Operand.col(valueColumn), Operand.col(BRANCH) }, false));
		}
		return new Exists(true, pipeline);
	}

	private static Kernel kernelWithNineColumns(List<Node> pipeline) {
		// Columns 0–4 are used by the outer LIBRARY 10 suffix. Columns 5–8 are isolated nested EXISTS scratch.
		return new Kernel(9, pipeline, countDistinctBranch());
	}

	private static void assertNestedDomainWitness(Exists nestedWitness, int domain, int keyColumn,
			int valueColumn, boolean nonReusableFilter) {
		assertTrue(nestedWitness.negated, "the nested NOT EXISTS must remain negated");
		assertEquals(nonReusableFilter ? 4 : 3, nestedWitness.pipeline.size());
		assertTrue(nestedWitness.pipeline.get(0) instanceof EnumerateDomain);
		EnumerateDomain nestedDomain = (EnumerateDomain) nestedWitness.pipeline.get(0);
		assertEquals(domain, nestedDomain.domain);
		assertEquals(keyColumn, nestedDomain.col);
		assertFalse(nestedDomain.sortedKeys, "nested domain ordering is not part of this rewrite proof");
		assertTrue(nestedWitness.pipeline.get(1) instanceof Probe);
		Probe probe = (Probe) nestedWitness.pipeline.get(1);
		assertEquals(domain, probe.adjacency);
		assertEquals(keyColumn, probe.key.index);
		assertEquals(valueColumn, probe.valueCol);
		assertTrue(nestedWitness.pipeline.get(2) instanceof FilterCompareId);
		FilterCompareId compare = (FilterCompareId) nestedWitness.pipeline.get(2);
		assertFalse(compare.negated, "the nested witness compares the probe result to the outer counted key");
		assertEquals(valueColumn, compare.left.index);
		assertEquals(BRANCH, compare.right.index);
		if (nonReusableFilter) {
			assertTrue(nestedWitness.pipeline.get(3) instanceof FilterValue);
			assertFalse(((FilterValue) nestedWitness.pipeline.get(3)).reusable,
					"a non-reusable value filter remains an ordering barrier");
		}
	}

	private static void assertRewritten(Kernel kernel) {
		assertEquals(2, kernel.pipeline.size(), () -> "expected [root, Exists] but got " + kernel.shapeKey());
		assertTrue(kernel.pipeline.get(0) instanceof EnumerateDomain, kernel.shapeKey());
		assertTrue(kernel.pipeline.get(1) instanceof Exists, kernel.shapeKey());
		assertFalse(((Exists) kernel.pipeline.get(1)).negated, "the fold wraps the suffix in a positive witness");
		Aggregate terminal = (Aggregate) kernel.terminal;
		for (AggregateOutput output : terminal.outputs) {
			// A sorted domain may repeat a key once per context, so the rewrite keeps DISTINCT semantics through
			// the ordered last-seen accumulator instead of degrading to COUNT(*).
			assertEquals(LmdbNativeKernelIr.AGG_COUNT_DISTINCT, output.kind,
					"a domain root keeps DISTINCT counting");
			assertEquals(0, output.orderedDomain, "the count must ride the root domain's order proof");
		}
	}

	private static void assertNotRewritten(Kernel kernel, List<Node> original) {
		assertEquals(original.size(), kernel.pipeline.size(), kernel.shapeKey());
		Aggregate terminal = (Aggregate) kernel.terminal;
		for (AggregateOutput output : terminal.outputs) {
			assertEquals(LmdbNativeKernelIr.AGG_COUNT_DISTINCT, output.kind,
					"an unrewritten kernel keeps its COUNT DISTINCT terminal");
			assertEquals(-1, output.orderedDomain, "an unrewritten kernel keeps hashed DISTINCT counting");
		}
	}

